-- Generated by Supabase CLI as 20261102171221_access_inactivity_enforced.sql.
-- Corrects, without rewriting/reapplying, hosted 20261102154519 policies.
-- No auth.sessions writes. Provider session created_at is the first deadline anchor.
CREATE TABLE private.session_activities(
 user_id uuid NOT NULL REFERENCES auth.users(id),session_id uuid NOT NULL,
 last_activity_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,
 PRIMARY KEY(user_id,session_id)
);
ALTER TABLE private.session_activities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.session_activities FROM PUBLIC,anon,authenticated,service_role;
-- Retain policy history so even a session first seen after an increase cannot revive.
CREATE TABLE private.access_policy_history(
 office_id uuid NOT NULL REFERENCES public.offices(id),audience text NOT NULL CHECK(audience IN('team','client')),
 revision integer NOT NULL, effective_at timestamptz NOT NULL,idle_minutes integer NOT NULL CHECK(idle_minutes BETWEEN 5 AND 1440),
 PRIMARY KEY(office_id,audience,revision)
);
ALTER TABLE private.access_policy_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.access_policy_history FROM PUBLIC,anon,authenticated,service_role;
INSERT INTO private.access_policy_history SELECT office_id,audience,revision,'-infinity'::timestamptz,idle_minutes FROM private.access_policies;
CREATE FUNCTION private.access_policy_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 INSERT INTO private.access_policy_history(office_id,audience,revision,effective_at,idle_minutes)
 VALUES(NEW.office_id,NEW.audience,NEW.revision,clock_timestamp(),NEW.idle_minutes);
 RETURN NEW;
END$$;
CREATE TRIGGER access_policy_record AFTER INSERT OR UPDATE ON private.access_policies FOR EACH ROW EXECUTE FUNCTION private.access_policy_record();
CREATE TRIGGER access_policy_history_immutable BEFORE UPDATE OR DELETE ON private.access_policy_history FOR EACH ROW EXECUTE FUNCTION private.templates_immutable20();
CREATE FUNCTION private.access_office_policies() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
 INSERT INTO private.access_policies(office_id,audience,idle_minutes) SELECT NEW.id,a,30 FROM unnest(ARRAY['team','client']) a ON CONFLICT DO NOTHING;
 RETURN NEW;
END$$;
CREATE TRIGGER access_office_policies AFTER INSERT ON public.offices FOR EACH ROW EXECUTE FUNCTION private.access_office_policies();

CREATE FUNCTION private.session_activity_minutes(p_user_id uuid) RETURNS integer LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce(min(coalesce(p.idle_minutes,30)),30)::integer FROM public.memberships m
 JOIN public.profiles pr ON pr.id=m.user_id AND pr.active JOIN public.offices o ON o.id=m.office_id AND o.active
 JOIN public.roles r ON r.code=m.role_code AND r.active
 LEFT JOIN private.access_policies p ON p.office_id=m.office_id AND p.audience=CASE WHEN m.role_code='client' THEN 'client' ELSE 'team' END
 WHERE m.user_id=p_user_id AND m.active;
$$;
CREATE FUNCTION private.session_activity_deadline(p_user_id uuid,p_session_id uuid) RETURNS timestamptz LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE provider_session jsonb;anchor timestamptz;deadline timestamptz;history_minutes integer;a private.session_activities;
BEGIN
 SELECT to_jsonb(s) INTO provider_session FROM auth.sessions s JOIN auth.users u ON u.id=s.user_id
 WHERE s.id=p_session_id AND s.user_id=p_user_id AND(s.not_after IS NULL OR s.not_after>clock_timestamp())
 AND u.email_confirmed_at IS NOT NULL AND NOT u.is_anonymous AND u.deleted_at IS NULL AND(u.banned_until IS NULL OR u.banned_until<=clock_timestamp());
 IF provider_session IS NULL THEN RETURN NULL;END IF;
 anchor:=(provider_session->>'created_at')::timestamptz;
 IF anchor IS NULL OR anchor>clock_timestamp() THEN RETURN NULL;END IF;
 SELECT * INTO a FROM private.session_activities WHERE user_id=p_user_id AND session_id=p_session_id;
 IF a.session_id IS NOT NULL THEN anchor:=a.last_activity_at;deadline:=a.expires_at;END IF;
 SELECT min(h.idle_minutes) INTO history_minutes FROM (
  SELECT h.*,lead(h.effective_at,1,'infinity'::timestamptz) OVER(PARTITION BY h.office_id,h.audience ORDER BY h.revision) until_at
  FROM private.access_policy_history h WHERE EXISTS(SELECT FROM public.memberships m WHERE m.user_id=p_user_id AND m.active AND m.office_id=h.office_id AND h.audience=CASE WHEN m.role_code='client' THEN 'client' ELSE 'team' END)
 ) h JOIN public.memberships m ON m.office_id=h.office_id AND m.user_id=p_user_id AND m.active
 AND h.audience=CASE WHEN m.role_code='client' THEN 'client' ELSE 'team' END
 WHERE h.effective_at<=clock_timestamp() AND h.until_at>anchor;
 RETURN least(deadline,anchor+make_interval(mins=>least(coalesce(history_minutes,30),private.session_activity_minutes(p_user_id))));
END$$;
-- Explicit IDs only: workers validate the UID/session recorded by their own lease,
-- never inherit service_role JWT claims as a human identity.
CREATE FUNCTION private.session_activity_valid(p_user_id uuid,p_session_id uuid) RETURNS boolean LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce(private.session_activity_deadline(p_user_id,p_session_id)>clock_timestamp(),false);
$$;
CREATE OR REPLACE FUNCTION private.team_require_identity() RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path='' AS $$
DECLARE caller uuid:=auth.uid();sid uuid;
BEGIN
 BEGIN sid:=(auth.jwt()->>'session_id')::uuid;EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='PT401';END;
 IF caller IS NULL OR sid IS NULL OR NOT private.session_activity_valid(caller,sid) THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='PT401';END IF;
 RETURN caller;
END$$;
CREATE OR REPLACE FUNCTION private.current_permissions(p_office_id uuid) RETURNS text[] LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce((SELECT private.team_permissions_for_member(m.id) FROM public.memberships m
 JOIN auth.sessions s ON s.user_id=m.user_id AND s.id::text=auth.jwt()->>'session_id'
 WHERE m.office_id=p_office_id AND m.user_id=auth.uid() AND private.session_activity_valid(m.user_id,s.id)),ARRAY[]::text[]);
$$;

CREATE FUNCTION private.session_activity(p_human boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid;sid uuid;anchor timestamptz;deadline timestamptz;t timestamptz;minutes integer;a private.session_activities;provider_session jsonb;
BEGIN
 IF p_human IS NULL OR current_setting('role',true)<>'authenticated' OR coalesce(auth.jwt()->>'role','authenticated')<>'authenticated' THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='PT401';END IF;
 actor:=private.team_require_identity();sid:=(auth.jwt()->>'session_id')::uuid;
 -- Lock order: policies (stable office/audience order), then this activity row.
 -- A policy setter only locks membership then policy and never acquires activities.
 PERFORM 1 FROM private.access_policies p WHERE EXISTS(SELECT FROM public.memberships m WHERE m.user_id=actor AND m.active AND m.office_id=p.office_id AND p.audience=CASE WHEN m.role_code='client' THEN 'client' ELSE 'team' END) ORDER BY p.office_id,p.audience FOR SHARE OF p;
 SELECT to_jsonb(s) INTO provider_session FROM auth.sessions s WHERE s.id=sid AND s.user_id=actor;
 anchor:=(provider_session->>'created_at')::timestamptz;
 deadline:=private.session_activity_deadline(actor,sid);
 IF deadline IS NULL OR deadline<=clock_timestamp() OR anchor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='PT401';END IF;
 INSERT INTO private.session_activities(user_id,session_id,last_activity_at,expires_at) VALUES(actor,sid,anchor,deadline) ON CONFLICT DO NOTHING;
 SELECT * INTO a FROM private.session_activities WHERE user_id=actor AND session_id=sid FOR UPDATE;
 -- Recheck after every wait, using wall time and freshly visible authority.
 PERFORM private.team_require_identity();deadline:=private.session_activity_deadline(actor,sid);t:=clock_timestamp();minutes:=private.session_activity_minutes(actor);
 IF deadline IS NULL OR deadline<=t THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='PT401';END IF;
 IF p_human AND a.last_activity_at<=t-interval '15 seconds' THEN
  deadline:=t+make_interval(mins=>minutes);
  UPDATE private.session_activities SET last_activity_at=t,expires_at=deadline WHERE user_id=actor AND session_id=sid;
 END IF;
 RETURN jsonb_build_object('user_id',actor,'session_id',sid,'server_time',t,'expires_at',deadline,'idle_minutes',minutes);
END$$;
CREATE FUNCTION public.session_activity(p_human boolean DEFAULT false) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$SELECT private.session_activity(p_human);$$;

CREATE OR REPLACE FUNCTION private.access_policies_state(p_office_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid;m public.memberships;p jsonb;
BEGIN
 actor:=private.team_require_identity();SELECT * INTO m FROM public.memberships WHERE office_id=p_office_id AND user_id=actor AND active;
 IF m.id IS NULL OR m.role_code NOT IN('owner','admin') OR NOT private.current_permissions(p_office_id) @> ARRAY['foundation.access','access.manage'] THEN RAISE EXCEPTION 'ACCESS_FORBIDDEN' USING ERRCODE='PT403';END IF;
 SELECT jsonb_object_agg(audience,jsonb_build_object('audience',audience,'idle_minutes',idle_minutes,'revision',revision,'updated_at',updated_at)) INTO p FROM private.access_policies WHERE office_id=p_office_id;
 RETURN jsonb_build_object('policies',coalesce(p,'{}'::jsonb),'audience','team','can_manage',true);
END$$;
CREATE OR REPLACE FUNCTION private.access_policies_set(p_office_id uuid,p_audience text,p_idle_minutes integer,p_expected_revision integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid;m public.memberships;current private.access_policies;cmd private.access_policy_commands;
BEGIN
 actor:=private.team_require_identity();
 IF p_idempotency_key IS NULL OR p_audience IS NULL OR p_audience NOT IN('team','client') OR p_idle_minutes IS NULL OR p_idle_minutes NOT BETWEEN 5 AND 1440 OR p_expected_revision IS NULL OR p_expected_revision NOT BETWEEN 0 AND 2147483645 THEN RAISE EXCEPTION 'ACCESS_VALIDATION' USING ERRCODE='PT422';END IF;
 SELECT * INTO m FROM public.memberships WHERE office_id=p_office_id AND user_id=actor AND active FOR UPDATE;
 PERFORM private.access_policies_state(p_office_id);
 INSERT INTO private.access_policies(office_id,audience,idle_minutes) SELECT p_office_id,a,30 FROM unnest(ARRAY['team','client']) a ON CONFLICT DO NOTHING;
 SELECT * INTO current FROM private.access_policies WHERE office_id=p_office_id AND audience=p_audience FOR UPDATE;
 -- Permissions/session may have changed while waiting on membership/policy.
 PERFORM private.access_policies_state(p_office_id);
 SELECT * INTO cmd FROM private.access_policy_commands WHERE office_id=p_office_id AND actor_id=actor AND idempotency_key=p_idempotency_key;
 IF FOUND THEN
  IF cmd.audience<>p_audience OR cmd.idle_minutes<>p_idle_minutes OR cmd.expected_revision<>p_expected_revision THEN RAISE EXCEPTION 'ACCESS_CONFLICT' USING ERRCODE='PT409';END IF;
  RETURN private.access_policies_state(p_office_id);
 END IF;
 IF current.revision<>p_expected_revision THEN RAISE EXCEPTION 'ACCESS_CONFLICT' USING ERRCODE='PT409';END IF;
 UPDATE private.access_policies SET idle_minutes=p_idle_minutes,revision=revision+1,updated_at=clock_timestamp(),updated_by=actor WHERE office_id=p_office_id AND audience=p_audience;
 INSERT INTO private.access_policy_commands(office_id,actor_id,idempotency_key,audience,idle_minutes,expected_revision) VALUES(p_office_id,actor,p_idempotency_key,p_audience,p_idle_minutes,p_expected_revision);
 PERFORM private.team_audit(p_office_id,actor,'access.policy_updated','office',p_office_id,p_idempotency_key,jsonb_build_object('audience',p_audience,'idle_minutes',p_idle_minutes,'revision',current.revision+1));
 -- Reducing one's own deadline can expire it immediately; the successful commit
 -- must survive. Do not call an identity-guarded state helper after this point.
 RETURN jsonb_build_object('policies',(SELECT jsonb_object_agg(audience,jsonb_build_object('audience',audience,'idle_minutes',idle_minutes,'revision',revision,'updated_at',updated_at)) FROM private.access_policies WHERE office_id=p_office_id),'audience','team','can_manage',true);
END$$;

REVOKE ALL ON FUNCTION private.access_policy_record(),private.access_office_policies(),private.session_activity_minutes(uuid),private.session_activity_deadline(uuid,uuid),private.session_activity_valid(uuid,uuid),private.session_activity(boolean),public.session_activity(boolean) FROM PUBLIC,anon,authenticated,service_role;
